function compile(t) {
  const a = t.startsWith('^'), z = t.endsWith('$');
  const body = t.slice(a ? 1 : 0, z ? -1 : undefined);
  const src = body.split(/(\{n\}|\{\}|s\?)/).map((p) => (p === '{}' ? '(.+?)' : p === '{n}' ? '(\\d[\\d.,\\u00a0\\u202f ]*\\d|\\d)' : p === 's?' ? 's?' : p.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&'))).join('');
  return new RegExp((a ? '^' : '') + src + (z ? '$' : ''));
}
const cache = {};
/** Rules for one language as [RegExp, replacement] pairs, in order. */
export function rulesFor(code) {
  const i = { el: 1, es: 2, fr: 3 }[code];
  if (!i) return [];
  return (cache[code] ||= R.map((r) => [compile(r[0]), r[i]]));
}
